import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.CLq81i8L.js";const u=JSON.parse('{"title":"AI App Architecture & Layers","description":"","frontmatter":{"title":"AI App Architecture & Layers"},"headers":[],"relativePath":"en/ai/app/architecture.md","filePath":"en/ai/app/architecture.md","lastUpdated":1786936077000}'),r={name:"en/ai/app/architecture.md"};function a(i,e,c,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ai-app-architecture-layers" tabindex="-1">AI App Architecture &amp; Layers <a class="header-anchor" href="#ai-app-architecture-layers" aria-label="Permalink to &quot;AI App Architecture &amp; Layers&quot;">​</a></h1><blockquote><p>Implementation-level structure of the <code>ai/app/</code> frontend: directory rules, Store / Composable / API inventory, plugin adapter and Harness client.</p></blockquote><h2 id="_1-layering-rules" tabindex="-1">1. Layering Rules <a class="header-anchor" href="#_1-layering-rules" aria-label="Permalink to &quot;1. Layering Rules&quot;">​</a></h2><p>AI App follows the platform-wide layering (same as editor / flow / ua):</p><table tabindex="0"><thead><tr><th>Layer</th><th>Location</th><th>Responsibility</th><th>Constraint</th></tr></thead><tbody><tr><td>Views</td><td><code>views/</code></td><td>Route-level page assembly</td><td>Page orchestration only; no complex business logic</td></tr><tr><td>UI components</td><td><code>components/</code></td><td>Reusable render components</td><td>Render only; business logic moves to composables/stores</td></tr><tr><td>Global state</td><td><code>stores/</code></td><td>Pinia stores</td><td>Single exit for global state; no bare cross-page state in components</td></tr><tr><td>Shared logic</td><td><code>composables/</code></td><td><code>useXXX</code> composables</td><td>Shared logic uses composables, not scattered utils</td></tr><tr><td>API aggregation</td><td><code>api/</code></td><td>All backend requests</td><td>Components/stores/composables must not call <code>fetch()</code> directly</td></tr><tr><td>Plugin adapter</td><td><code>plugins/</code></td><td>DSH/Cordis plugin container</td><td>Business code only imports from <code>@/plugins</code></td></tr><tr><td>Constants</td><td><code>constants/</code></td><td>Static enums/metadata</td><td>errorCodes, node types, model provider metadata</td></tr><tr><td>Types</td><td><code>types/</code></td><td>Local protocol types</td><td>Cross-project shared types live in <code>platform-shared/ai</code></td></tr></tbody></table><h2 id="_2-api-layer-src-api" tabindex="-1">2. API Layer (src/api/) <a class="header-anchor" href="#_2-api-layer-src-api" aria-label="Permalink to &quot;2. API Layer (src/api/)&quot;">​</a></h2><p>All backend requests go through <code>src/api/</code>; <code>api/shared/request.ts</code> provides the unified request wrapper (token injection, tenant header <code>X-Tenant-Id</code>, error handling), <code>api/shared/blobRequest.ts</code> for binary streams.</p><table tabindex="0"><thead><tr><th>Module</th><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>aiApi/</code></td><td><code>base.ts</code></td><td>AI API base class and generic requests</td></tr><tr><td></td><td><code>conversation.ts</code></td><td>Conversation CRUD, messages, streaming (WebSocket)</td></tr><tr><td></td><td><code>document.ts</code></td><td>Document upload/parse</td></tr><tr><td></td><td><code>evaluation.ts</code></td><td>Evaluation datasets and runs</td></tr><tr><td></td><td><code>llm.ts</code></td><td>LLM calls and config</td></tr><tr><td></td><td><code>mcp.ts</code></td><td>MCP server management</td></tr><tr><td></td><td><code>memory.ts</code></td><td>Memory management</td></tr><tr><td></td><td><code>monitor.ts</code></td><td>Agent monitoring stats</td></tr><tr><td></td><td><code>rag.ts</code></td><td>Knowledge base / retrieval</td></tr><tr><td></td><td><code>workflowTemplate.ts</code></td><td>Workflow templates</td></tr><tr><td><code>agentWorkflowApi.ts</code></td><td>Workflow CRUD, publish, execute, HITL resume, invoke</td><td></td></tr><tr><td><code>workflowInvokeApi.ts</code></td><td>External integration invoke calls</td><td></td></tr><tr><td><code>apiKeyApi.ts</code> / <code>tenantApi.ts</code></td><td>API keys / tenants</td><td></td></tr><tr><td><code>modelApi.ts</code> / <code>modelConfigApi.ts</code> / <code>providerApi.ts</code></td><td>Models / model config / providers</td><td></td></tr><tr><td><code>pluginApi.ts</code> / <code>tenantPluginApi.ts</code></td><td>Plugin center / tenant plugins</td><td></td></tr><tr><td><code>harness/index.ts</code></td><td>Harness runtime client (below)</td><td></td></tr></tbody></table><blockquote><p>API integration follows existing server contracts (the frontend never modifies <code>server/</code>); new endpoints are aggregated in <code>api/</code> first.</p></blockquote><h2 id="_3-pinia-stores-src-stores" tabindex="-1">3. Pinia Stores (src/stores/) <a class="header-anchor" href="#_3-pinia-stores-src-stores" aria-label="Permalink to &quot;3. Pinia Stores (src/stores/)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Store</th><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>useAiStore</code></td><td><code>ai.ts</code></td><td>Compatibility main store (entry before <code>stores/ai/</code> split)</td></tr><tr><td></td><td><code>ai/actions.ts</code></td><td>AI action dispatch (generation/tool calls)</td></tr><tr><td></td><td><code>ai/events.ts</code></td><td>Streaming event handling (v1/v2 events → state)</td></tr><tr><td></td><td><code>ai/requirement.ts</code></td><td>Requirement analysis/confirmation state</td></tr><tr><td></td><td><code>ai/workflow.ts</code></td><td>Workflow-related state</td></tr><tr><td><code>useConversationStore</code></td><td><code>conversation.ts</code></td><td>Conversation list / current session</td></tr><tr><td><code>useStreamStore</code></td><td><code>stream.ts</code></td><td>WebSocket stream buffering and event queue</td></tr><tr><td><code>useSchemaStore</code></td><td><code>schema.ts</code></td><td>Current schema and version comparison</td></tr><tr><td><code>useRAGStore</code></td><td><code>rag.ts</code></td><td>RAG retrieval state</td></tr><tr><td><code>useChatSettingsStore</code></td><td><code>chatSettings.ts</code></td><td>Chat settings (model/params)</td></tr><tr><td><code>useChatConfigStore</code></td><td><code>chatConfig.ts</code></td><td>Chat configuration</td></tr><tr><td><code>useHITLStore</code></td><td><code>hitl.ts</code></td><td>HITL interrupt/resume state</td></tr><tr><td><code>useAgentWorkflowDesignerStore</code></td><td><code>agentWorkflowDesigner.ts</code></td><td>Designer canvas/node/edge state</td></tr><tr><td><code>usePublishedAgentWorkflowsStore</code></td><td><code>publishedAgentWorkflows.ts</code></td><td>Published workflow cache</td></tr></tbody></table><p>Unified exports in <code>stores/index.ts</code> (<code>useAiStore</code> kept for backward compatibility).</p><h2 id="_4-composables-src-composables" tabindex="-1">4. Composables (src/composables/) <a class="header-anchor" href="#_4-composables-src-composables" aria-label="Permalink to &quot;4. Composables (src/composables/)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>Composables</th></tr></thead><tbody><tr><td>Chat</td><td><code>useChatAttachments</code> (multimodal attachments), <code>useChatScroll</code>, <code>useSmartSuggestions</code>, <code>useActionProposals</code></td></tr><tr><td>Workflow execution</td><td><code>useWorkflowChatExecution</code>, <code>useWorkflowExecutionStream</code>, <code>useWorkflowInvoke</code>, <code>useWorkflowInvokeInfo</code>, <code>useWorkflowSelfTest</code>, <code>useWorkflowSuggestion</code>, <code>useWorkflowTemplates</code>, <code>usePublishedAgentWorkflows</code></td></tr><tr><td>Designer</td><td><code>useAgentNodePropertyPanel</code> (property panel registration), <code>useEdgePath</code>, <code>useFlowPreview</code>, <code>useWorkflowActions</code></td></tr><tr><td>Models</td><td><code>useModelCenter</code>, <code>useModelOptions</code>, <code>useModelPresets</code></td></tr><tr><td>Plugins</td><td><code>usePluginRegistry</code> (registry snapshot), <code>usePluginRuntime</code>, <code>useMcpHealth</code></td></tr><tr><td>Preview</td><td><code>usePreviewCompare</code>, <code>usePreviewInteraction</code></td></tr><tr><td>Shell embed</td><td><code>useShellEmbed</code> (qiankun/iframe embed detection and context bridge)</td></tr><tr><td>Monitor / i18n</td><td><code>useAiMonitor</code>, <code>useAiLocale</code></td></tr></tbody></table><h2 id="_5-dsh-cordis-plugin-adapter-src-plugins" tabindex="-1">5. DSH/Cordis Plugin Adapter (src/plugins/) <a class="header-anchor" href="#_5-dsh-cordis-plugin-adapter-src-plugins" aria-label="Permalink to &quot;5. DSH/Cordis Plugin Adapter (src/plugins/)&quot;">​</a></h2><p>M0 plugin-system integration (design basis: <code>ai/docs/design/dsh-cordis-integration.md</code>). <strong>Business code only imports from <code>@/plugins</code></strong>; direct imports of <code>@deepseek-ai/cordis</code> / <code>@deepseek-ai/dsh-*</code> are forbidden — Cordis API changes only affect the adapter internals.</p><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>index.ts</code></td><td>Single exit (host lifecycle, serviceState, builtin tools, layers, adapter conversions, palette items)</td></tr><tr><td><code>host.ts</code></td><td>Plugin host lifecycle: <code>startPluginHost</code> / <code>ensurePluginHost</code> / <code>stopPluginHost</code></td></tr><tr><td><code>bridge.ts</code></td><td>Bridge service state (<code>serviceState</code>)</td></tr><tr><td><code>config/builtin.ts</code></td><td>Builtin tool definitions and categories (<code>BUILT_IN_TOOLS</code>)</td></tr><tr><td><code>config/layers.ts</code></td><td>Config layering: <code>builtin &lt; registry overlay &lt; local patch</code> (<code>mergeLayers</code>)</td></tr><tr><td><code>config/nodeTypes.ts</code></td><td>Agent canvas palette items and node colors (<code>AGENT_PALETTE_ITEMS</code>)</td></tr><tr><td><code>config/renderers.ts</code></td><td>Message renderer registration</td></tr><tr><td><code>registry-adapter.ts</code></td><td>Server registry tools → adapter tool definitions (<code>registryToolToDef</code>)</td></tr><tr><td><code>skill-adapter.ts</code></td><td>Platform skills → adapter skill definitions (<code>platformSkillToDef</code>)</td></tr><tr><td><code>plugins/chat-tools</code></td><td>Tool definition types and categories (<code>ToolDef</code> / <code>ToolCategory</code>)</td></tr><tr><td><code>plugins/node-types</code> / <code>plugins/renderers</code></td><td>Node type / renderer plugins</td></tr></tbody></table><p><strong>Iron rules</strong> (see <code>ai/CLAUDE.md</code>):</p><ul><li>Plugins (code) load statically; tools / workflows / skills are data, registered dynamically by plugin runtime (<code>chatTools.setOverlay</code> / <code>ctx.tools.register</code>)</li><li>A workflow is always data, never a plugin; no runtime dynamic import of loaders in the browser</li><li>Version lock: <code>@deepseek-ai/cordis@4.0.1</code>, <code>@deepseek-ai/dsh@0.1.0-rc.6</code> exact versions; upgrades require per-package review</li></ul><h2 id="_6-harness-client-trace-protocol" tabindex="-1">6. Harness Client &amp; Trace Protocol <a class="header-anchor" href="#_6-harness-client-trace-protocol" aria-label="Permalink to &quot;6. Harness Client &amp; Trace Protocol&quot;">​</a></h2><h3 id="_6-1-client-src-api-harness" tabindex="-1">6.1 Client (src/api/harness/) <a class="header-anchor" href="#_6-1-client-src-api-harness" aria-label="Permalink to &quot;6.1 Client (src/api/harness/)&quot;">​</a></h3><p>Typed calls from <code>ai/app</code> to <code>ai/harness</code> (DSH agent runtime):</p><table tabindex="0"><thead><tr><th>Function</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>startHarnessSession()</code></td><td><code>POST /session/start</code></td><td>Create a persistent agent session</td></tr><tr><td><code>sendHarnessMessage(sessionId, content)</code></td><td><code>POST /session/:id/message</code></td><td>Submit a message, wait until settled → <code>{ text, reason }</code></td></tr><tr><td><code>fetchHarnessTrace(sessionId)</code></td><td><code>GET /session/:id/trace</code></td><td>Fetch <code>platform.nodeTrace</code> projection snapshot</td></tr><tr><td><code>subscribeHarnessEvents(sessionId, onEvents)</code></td><td><code>GET /session/:id/events</code> (SSE)</td><td>Subscribe to session event deltas; returns an unsubscribe function</td></tr></tbody></table><p>Env vars: <code>VITE_HARNESS_BASE_URL</code> (default <code>/schema-platform/harness</code>), <code>VITE_HARNESS_TOKEN</code> (POC default <code>poc-token</code>). SSE uses query token in POC because EventSource cannot set custom headers.</p><h3 id="_6-2-trace-protocol-src-types-harnesstrace-ts" tabindex="-1">6.2 Trace Protocol (src/types/harnessTrace.ts) <a class="header-anchor" href="#_6-2-trace-protocol-src-types-harnesstrace-ts" aria-label="Permalink to &quot;6.2 Trace Protocol (src/types/harnessTrace.ts)&quot;">​</a></h3><p>Read model of DSH session traces, 1:1 with the trajectory-forward plugin (zod schema) in <code>ai/harness</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AgentNodeTrace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  turns</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AgentNodeTraceTurn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// turn start/end seq and end reason</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  toolCalls</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AgentNodeTraceToolCall</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tool calls: callId/turn/step/name/arguments/resultSeq/isError</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  messages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AgentNodeTraceMessage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// model messages: turn/step/text</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Optional fields always exist, <code>null</code> when absent (aligned with zod nullable). Will move to <code>shared/platform-shared/ai</code> when formalized (cross-project, needs approval).</p><h3 id="_6-3-consumers" tabindex="-1">6.3 Consumers <a class="header-anchor" href="#_6-3-consumers" aria-label="Permalink to &quot;6.3 Consumers&quot;">​</a></h3><ul><li><code>views/HarnessTraceView.vue</code> (route <code>/debug/harness</code>): session create → message → trace/events view</li><li><code>views/AgentExecutionDetailView.vue</code>: execution detail node-level monitoring</li></ul><h2 id="_7-i18n-telemetry" tabindex="-1">7. i18n &amp; Telemetry <a class="header-anchor" href="#_7-i18n-telemetry" aria-label="Permalink to &quot;7. i18n &amp; Telemetry&quot;">​</a></h2><ul><li><strong>i18n</strong>: <code>locales/zh-CN.ts</code> / <code>locales/en-US.ts</code>; <code>useAiLocale</code> reads/writes local language preference</li><li><strong>Telemetry</strong>: <code>utils/telemetry.ts</code> (<code>initAiTelemetry</code> / <code>disposeAiTelemetry</code>) for AI interaction events</li><li><strong>Theme</strong>: <code>styles/ai-theme-bridge.scss</code>, <code>graphEdgeStates.scss</code> bridge platform-shared theme variables and canvas edge states</li></ul><h2 id="_8-testing" tabindex="-1">8. Testing <a class="header-anchor" href="#_8-testing" aria-label="Permalink to &quot;8. Testing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Location</th><th>Description</th></tr></thead><tbody><tr><td>Unit (Vitest)</td><td><code>src/__tests__/</code>, <code>stores/__tests__/</code>, <code>stores/ai/__tests__/</code>, <code>api/*.spec.ts</code>, <code>plugins/__tests__/</code></td><td>Store behavior, API wrappers, adapter conversions, message components</td></tr><tr><td>E2E (Playwright)</td><td><code>e2e/auth.spec.ts</code></td><td>Auth flow (<code>pnpm test:e2e</code>)</td></tr><tr><td>Type check</td><td>—</td><td><code>pnpm typecheck</code> (vue-tsc --noEmit)</td></tr></tbody></table><h2 id="_9-related-docs" tabindex="-1">9. Related Docs <a class="header-anchor" href="#_9-related-docs" aria-label="Permalink to &quot;9. Related Docs&quot;">​</a></h2><ul><li><a href="./index.html">App Overview</a> — positioning, features, run &amp; embed modes</li><li><a href="./routing.html">Routing &amp; Pages</a> — full route table and guards</li><li><a href="./../harness.html">Harness Runtime</a> — DSH agent runtime service</li><li><a href="./../ai-shared.html">ai-shared API</a> — shared types/events/prompts</li><li><a href="./../design/overview.html">Design Overview</a> — information architecture wireframes</li></ul>`,36)])])}const g=t(r,[["render",a]]);export{u as __pageData,g as default};
